import{_ as t,o as r,c as a,a2 as d}from"./chunks/framework.B3-dzFNu.js";const u=JSON.parse('{"title":"Read the results","description":"","frontmatter":{},"headers":[],"relativePath":"results.md","filePath":"results.md","lastUpdated":1793498569000}'),o={name:"results.md"};function i(n,e,s,c,l,h){return r(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="read-the-results" tabindex="-1">Read the results <a class="header-anchor" href="#read-the-results" aria-label="Permalink to &quot;Read the results&quot;">​</a></h1><p>Start with coverage, then inspect findings. A model can return no findings while some required files were never reviewed.</p><h2 id="_1-check-coverage" tabindex="-1">1. Check coverage <a class="header-anchor" href="#_1-check-coverage" aria-label="Permalink to &quot;1. Check coverage&quot;">​</a></h2><p>The terminal reports how many required files completed, failed, or were inert. It also reports reused results and retry recovery when applicable.</p><ul><li>Completed files have validated review records.</li><li>Failed or omitted required files make the review incomplete.</li><li>Excluded files, such as lock files or binary files, are recorded but are not reviewed.</li></ul><p>Missing or partial related context is reported separately. It is not evidence that the change has no callers or tests.</p><h2 id="_2-read-findings-before-applying-anything" tabindex="-1">2. Read findings before applying anything <a class="header-anchor" href="#_2-read-findings-before-applying-anything" aria-label="Permalink to &quot;2. Read findings before applying anything&quot;">​</a></h2><p>Findings include a location, severity, classification and explanation. They may include a suggested change and a fix prompt.</p><p>Redline validates result structure and authoritative diff evidence. That does not prove the model&#39;s diagnosis is correct. Check the code and the claimed impact before applying a suggestion. Redline does not apply it for you.</p><p>The <code>echo</code> harness always supplies a clean answer. Its result demonstrates integration, not review quality.</p><h2 id="_3-open-the-saved-review" tabindex="-1">3. Open the saved review <a class="header-anchor" href="#_3-open-the-saved-review" aria-label="Permalink to &quot;3. Open the saved review&quot;">​</a></h2><p>Use the artifact path printed at the end of the run. By default it is a new directory below <code>$XDG_STATE_HOME/redline/reviews/</code>, or <code>$HOME/.local/state/redline/reviews/</code>.</p><p>Inside that run directory:</p><table tabindex="0"><thead><tr><th>File or directory</th><th>Use it for</th></tr></thead><tbody><tr><td><code>reviews/review.md</code></td><td>Read the consolidated review</td></tr><tr><td><code>reviews/summary.json</code></td><td>Inspect run coverage, outcomes and telemetry</td></tr><tr><td><code>reviews/*.json</code></td><td>Inspect per-file records and the consolidated JSON review</td></tr><tr><td><code>capture.json</code></td><td>Check the exact revisions and captured working state</td></tr><tr><td><code>status.json</code></td><td>Check completion, failure, cancellation or deadline status</td></tr><tr><td><code>bundle/</code> and <code>source/</code></td><td>Inspect the authoritative change and captured source</td></tr></tbody></table><p>Every run gets a new directory. To choose a path, see <a href="/projects/redline/commands#save-output-to-a-chosen-directory">Save output</a>. Interrupted runs can retain partial artifacts; do not treat them as completed reviews.</p><h2 id="_4-interpret-the-exit-code" tabindex="-1">4. Interpret the exit code <a class="header-anchor" href="#_4-interpret-the-exit-code" aria-label="Permalink to &quot;4. Interpret the exit code&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>0</code></td><td>The run completed without meeting a selected failure policy. It can still contain findings.</td></tr><tr><td><code>1</code></td><td>An operational problem or incomplete required review</td></tr><tr><td><code>2</code></td><td>An invalid argument or configuration</td></tr><tr><td><code>3</code></td><td>Findings met the selected <code>--fail-on</code> threshold</td></tr><tr><td><code>4</code></td><td>The selected capability is not implemented</td></tr><tr><td><code>5</code></td><td>A reporter failed</td></tr><tr><td><code>130</code></td><td>Cancellation</td></tr></tbody></table><p>For example, <code>--fail-on high</code> fails on high or critical findings. Incomplete required coverage fails regardless of that threshold.</p><p>For more detail, see the <a href="/projects/redline/local-cli#output-and-exit-status">complete exit-status reference</a>. For JSON fields and publication records, see the <a href="/projects/redline/review-reporting">output schema</a>.</p>',19)])])}const f=t(o,[["render",i]]);export{u as __pageData,f as default};
